INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(36897, 'itIT', 'Nemesi: Diventare la morte', 'Uccidi un giocatore Umano in un combattimento PvP mentre sei su Draenor e ottieni il suo cuore.', 'Hai fatto la tua scelta e ben presto conosceranno la tua ira spietata, ma prima devi avventurarti nelle terre selvagge di Draenor e strappare il cuore ancora pulsante di un Umano in un combattimento mortale. Dopo che lo avrai fatto, torna qui con il tuo trofeo.$B$BCon il cuore del tuo nemico, gli spiriti si legheranno ai tuoi sensi, donandoti una vista e un udito migliorati, vantaggi essenziali per cacciare le tue prede e stabilire il tuo dominio.', '', '', '', '', '', 'Torna da Raza''kul al Santuario del Gladiatore.', 19865),
(36898, 'itIT', 'Tracking Quest: Delvar Ironfirst', '', '', '', '', '', '', '', '', 19865),
