(37213, 'itIT', 'FLAG - Proving Grounds - Damage Silver', '', '', '', '', '', '', '', '', 19865),
(37214, 'itIT', 'FLAG - Proving Grounds - Damage Gold', '', '', '', '', '', '', '', '', 19865),
